import 'dart:math' as math;

/// Gauss–Legendre quadrature.
///
/// Nodes are generated by Newton's method on the Legendre polynomial rather
/// than transcribed from a table, so any order can be requested and none of it
/// can be a typo.
///
/// An n-point rule integrates polynomials of degree up to 2n−1 exactly. More to
/// the point here, its error on a smooth integrand shrinks geometrically, so the
/// trigonometric integrands that arise over analytic surface patches reach
/// double-precision limits well before 16 points. That is why measurement on
/// this kernel can be called exact without qualification: the quadrature error
/// is smaller than the rounding error of the arithmetic around it.
class GaussLegendre {
  GaussLegendre._(this.nodes, this.weights);

  /// Abscissae on [-1, 1].
  final List<double> nodes;
  final List<double> weights;

  int get order => nodes.length;

  static final Map<int, GaussLegendre> _cache = {};

  factory GaussLegendre(int order) {
    if (order < 1) throw ArgumentError.value(order, 'order', 'must be >= 1');
    return _cache[order] ??= _build(order);
  }

  /// Enough for every integrand in this library, with margin.
  static GaussLegendre get standard => GaussLegendre(16);

  static GaussLegendre _build(int n) {
    final x = List<double>.filled(n, 0);
    final w = List<double>.filled(n, 0);
    for (var i = 0; i < n; i++) {
      // Tricomi's approximation for the i-th root, then Newton.
      var z = math.cos(math.pi * (i + 0.75) / (n + 0.5));
      var dp = 0.0;
      for (var iter = 0; iter < 100; iter++) {
        final (p, d) = _legendre(n, z);
        dp = d;
        final step = p / d;
        z -= step;
        if (step.abs() < 1e-16) break;
      }
      x[i] = z;
      w[i] = 2 / ((1 - z * z) * dp * dp);
    }
    return GaussLegendre._(x, w);
  }

  /// Legendre P_n(z) and P'_n(z) by the standard three-term recurrence.
  static (double, double) _legendre(int n, double z) {
    if (n == 0) return (1, 0);
    var p0 = 1.0;
    var p1 = z;
    for (var k = 2; k <= n; k++) {
      final p2 = ((2 * k - 1) * z * p1 - (k - 1) * p0) / k;
      p0 = p1;
      p1 = p2;
    }
    return (p1, n * (z * p1 - p0) / (z * z - 1));
  }

  double integrate(double a, double b, double Function(double) f) {
    if (a == b) return 0;
    final half = (b - a) / 2;
    final mid = (a + b) / 2;
    var sum = 0.0;
    for (var i = 0; i < nodes.length; i++) {
      sum += weights[i] * f(mid + half * nodes[i]);
    }
    return sum * half;
  }

  double integrate2(
    double u0,
    double u1,
    double v0,
    double v1,
    double Function(double u, double v) f,
  ) =>
      integrate(v0, v1, (v) => integrate(u0, u1, (u) => f(u, v)));
}
